// Limpieza y normalización de correos (unidad CODE)
// Saca el HTML, corta el historial del hilo y las firmas, y recorta el texto
// para no gastar tokens del LLM en ruido.
const MAX_CHARS = 1200;

function htmlATexto(html) {
  return String(html || '')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/(p|div|li|tr)>/gi, '\n')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'");
}

function normalizeContent(texto) {
  let limpio = String(texto || '').replace(/\r/g, '');
  // Cortar el historial del hilo: lo que viene después de "El ... escribió:" / "On ... wrote:"
  const cortes = [
    /^\s*El .{0,200}escribi[oó]:\s*$/im,
    /^\s*On .{0,200}wrote:\s*$/im,
    /^-{2,}\s*(Original Message|Mensaje original)\s*-{2,}/im,
    /^\s*De:\s.*$/im,
    /^\s*From:\s.*$/im,
    /^--\s*$/m,
    /^Enviado desde mi /im,
    /^Sent from my /im
  ];
  for (const patron of cortes) {
    const m = limpio.match(patron);
    if (m && m.index > 0) limpio = limpio.slice(0, m.index);
  }
  limpio = limpio
    .split('\n')
    .filter((linea) => !linea.trim().startsWith('>'))
    .join('\n')
    .replace(/[ \t]+/g, ' ')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
  return limpio.length > MAX_CHARS ? limpio.slice(0, MAX_CHARS) + '…' : limpio;
}

const correos = $input.all()
  .filter((item) => item.json && item.json.id)
  .map((item) => {
    const c = item.json;
    const cuerpo = c.text ? c.text : htmlATexto(c.html);
    return {
      id: c.id,
      threadId: c.threadId,
      de: (c.from && c.from.text) || '',
      asunto: c.subject || '(sin asunto)',
      fecha: c.date || '',
      cuerpo: normalizeContent(cuerpo)
    };
  });

return [{ json: { total: correos.length, correos } }];
